/* Vocab flashcards: Shop Safety. Row = [term, plain meaning, shop tip]. Easy words first. */
(window.MM_FLASH_DECKS = window.MM_FLASH_DECKS || {}).safe = {
P: [
  ["PPE", "Personal protective equipment: safety glasses, gloves, boots and hearing protection that guard you from injury.", "Safety glasses go on before you walk into the bay, not when the job looks risky."],
  ["Hearing protection", "Earplugs or muffs that block loud noise from air tools, grinders and engines.", "Impact guns and air chisels can damage hearing over time. Wear them."],
  ["Safety glasses (Z87)", "Impact-rated eye protection marked Z87 or Z87+.", "Wear them any time you're in the shop area."],
  ["Goggles", "Eye protection that seals all around the eyes.", "Use them for splashes: acid, coolant, brake fluid."],
  ["Face shield", "A clear shield that covers the whole face.", "Always wear safety glasses underneath."],
  ["Welding shade", "The darkness rating of a welding lens.", "Match the shade number to the welding process."],
  ["Nitrile gloves", "Disposable gloves that resist oil, fuel and many chemicals.", "Change them when torn or soaked."],
  ["Mechanic's gloves", "Padded fabric gloves for grip and knuckle protection.", "Not for chemicals; fabric soaks them up."],
  ["Cut-resistant gloves", "Gloves rated to resist cuts from sharp edges.", "Use them for sheet metal and glass."],
  ["Heat-resistant gloves", "Gloves for handling hot parts.", "Exhaust and turbo parts stay hot long after shutdown."],
  ["Insulating (lineman) gloves", "Rubber gloves rated for voltage, worn with leather protectors.", "Air-test before each use; retest at least every 6 months."],
  ["Glove air test", "Rolling the cuff to trap air and check for pinholes.", "Any leak means don't use the glove."],
  ["Safety-toe boots", "Boots with steel or composite toes (ASTM F2413).", "Also look for slip- and oil-resistant soles."],
  ["Earplugs", "Foam or molded plugs that go in the ear canal.", "Roll foam plugs tight and insert them fully."],
  ["Earmuffs", "Hearing protection that covers the whole ear.", "Glasses arms can break the seal; check the fit."],
  ["NRR", "Noise reduction rating printed on hearing protection.", "Real protection is usually less than the label."],
  ["85 dBA action level", "The 8-hour average noise level that starts OSHA's hearing program.", "Above it, hearing tests and protection are required."],
  ["N95", "A filtering facepiece that stops at least 95% of particles.", "It does nothing for vapors or gases."],
  ["Half-mask respirator", "A reusable mask with replaceable cartridges or filters.", "Requires medical clearance and a fit test."],
  ["Organic vapor cartridge", "A respirator cartridge that absorbs solvent and paint vapors.", "Change it on a set schedule."],
  ["Fit test", "A test that checks a tight-fitting respirator seals on your face.", "Repeat it at least once a year."],
  ["Seal check", "A quick pressure check every time you put on a respirator.", "Do it before every use."],
  ["PAPR", "Powered air-purifying respirator that blows filtered air into a hood or mask.", "Loose-fitting hoods work with beards."],
  ["Medical evaluation", "Clearance that you can safely wear a respirator.", "Required before fit testing."],
  ["Hazard assessment", "The employer's written review of shop hazards, used to pick PPE.", "Required by OSHA 1910.132(d)."],
  ["PPE training", "Training on when, what, how to wear, limits and care of PPE.", "Required before work that needs PPE."],
  ["Hierarchy of controls", "Elimination, substitution, engineering, administrative, then PPE.", "PPE is the last line of defense."],
  ["Engineering control", "A physical fix that reduces the hazard, like an exhaust hose.", "It works without anyone remembering to wear it."],
  ["Administrative control", "Changing how work is done, like rotating loud jobs.", "It cuts how long each person is exposed."],
  ["Substitution", "Swapping a hazardous product for a safer one.", "Example: a water-based cleaner instead of a solvent."],
  ["Coveralls", "One-piece work clothing.", "Keep them close-fitting and buttoned."],
  ["Jewelry hazard", "Rings, chains and watches can catch or conduct current.", "Take them off before work."],
  ["Long hair", "Hair can be pulled into belts and fans.", "Tie it back and tuck it in."],
  ["Knee pads", "Pads that protect your knees when kneeling.", "Concrete wears knees out over a career."],
  ["Bump cap", "A light hard cap for bumping your head under a lift.", "Not rated like a hard hat for falling objects."],
  ["Anti-fog lenses", "A lens coating that stops fogging.", "Fogged glasses get taken off, and that's when injuries happen."],
  ["Side shields", "Guards on safety glasses that block debris from the side.", "Many eye injuries come at an angle."],
  ["Contacts and chemicals", "Contact lenses can trap particles or chemicals against the eye.", "Wear goggles; tell first aiders you wear contacts."],
  ["PPE inspection", "Checking your gear for damage before each use.", "Replace anything cracked, torn or worn out."],
  ["Employer-paid PPE", "OSHA requires employers to pay for most required PPE.", "Ordinary safety-toe shoes and prescription safety glasses can be exceptions."],
  ["OSHA 1910.132", "The general OSHA rule for personal protective equipment.", "Requires a hazard assessment and training."],
  ["Certification of hazard assessment", "A written record that PPE hazards were checked.", "OSHA requires it to be in writing."],
  ["ANSI Z87.1", "The standard for safety eyewear.", "Look for Z87 on the frame or lens."],
  ["Z87+ marking", "Shows high-impact rating.", "Better protection for grinding and cutting."],
  ["Prescription safety glasses", "Safety glasses with your prescription.", "Must still be Z87 rated."],
  ["Over-the-glasses goggles", "Goggles that fit over regular glasses.", "Regular glasses alone aren't safety glasses."],
  ["Chemical splash goggles", "Sealed goggles with indirect vents.", "Use for acids and pouring chemicals."],
  ["Impact goggles", "Goggles for flying chips.", "Direct vents; not for splashes."],
  ["Auto-darkening helmet", "A welding helmet that darkens when the arc starts.", "Check the battery and set the shade."],
  ["Welding gloves", "Thick leather gloves for welding heat.", "Keep them dry; wet gloves conduct."],
  ["Welding jacket", "Flame-resistant jacket for welding.", "Cotton or leather; never synthetics."],
  ["Hearing conservation program", "Required when noise averages 85 dBA or more over 8 hours.", "OSHA 1910.95; includes testing and training."],
  ["90 dBA PEL", "OSHA's noise limit over 8 hours.", "Above it, controls or protection are required."],
  ["Audiogram", "A hearing test.", "Done yearly in a hearing conservation program."],
  ["Standard threshold shift", "A measurable hearing loss on a hearing test.", "Must be reported to the worker."],
  ["Double hearing protection", "Earplugs plus earmuffs.", "For very loud jobs."],
  ["Earplug insertion", "Roll, pull the ear up, insert, hold.", "A poor fit gives little protection."],
  ["ANSI Z89.1", "The standard for hard hats.", "Needed where things can fall on you."],
  ["Bump cap vs hard hat", "Bump caps protect only from minor bumps.", "Not a substitute where a hard hat is required."],
  ["ASTM F2413", "The standard for safety-toe footwear.", "Look for it on the label."],
  ["Electrical hazard (EH) boots", "Boots with extra electrical resistance.", "A backup layer, not a primary protection."],
  ["Slip-resistant soles", "Soles that grip oily floors.", "A must in shops."],
  ["Metatarsal guard", "Protects the top of the foot.", "For heavy dropped parts."],
  ["Chemical-resistant gloves", "Gloves rated for specific chemicals.", "Check the chart; nitrile isn't good for everything."],
  ["Glove breakthrough time", "How long a chemical takes to get through a glove.", "Change gloves before that time."],
  ["Disposable gloves limit", "Thin gloves tear easily.", "Double up or use thicker gloves for solvents."],
  ["Latex allergy", "An allergy to latex gloves.", "Nitrile is the common alternative."],
  ["Respirator program", "A written program for required respirator use (1910.134).", "Includes medical clearance and fit tests."],
  ["Annual fit test", "Fit testing at least once a year.", "Also after face changes like weight loss."],
  ["Facial hair and respirators", "Beards break the seal of tight-fitting masks.", "Clean-shaven where the seal touches."],
  ["Voluntary respirator use", "Wearing a respirator when not required.", "OSHA Appendix D info must be given."],
  ["Cartridge change schedule", "When to replace respirator cartridges.", "Follow the program; don't wait to smell it."],
  ["P100 filter", "A filter for 99.97% of particles, oil-proof.", "Magenta color; for dust and fumes."],
  ["Dust mask vs respirator", "Some dust masks aren't NIOSH-approved respirators.", "Look for the NIOSH marking."],
  ["Apron", "Protects clothing and skin from chemicals.", "Chemical-resistant for battery work."],
  ["Sleeve guards", "Protect forearms from cuts and burns.", "Useful for grinding and handling sharp metal."],
  ["Hi-vis vest", "A bright vest so drivers see you.", "Wear near traffic or in the lot."],
  ["Cooling gear", "Vests or towels that keep you cool.", "Helps in hot shops."],
  ["PPE replacement", "Damaged PPE must be replaced.", "Employers generally pay for required PPE."],
  ["Personal clothing", "Loose clothes catch in machinery.", "Tuck shirts and roll sleeves safely."]
],
Z: [
  ["SDS", "Safety Data Sheet: the sheet that lists a chemical's hazards, first aid, PPE and spill steps.", "Every chemical in the shop has one. Know where the binder or the QR code is."],
  ["Used oil", "Engine oil that has been drained; a regulated waste that must be stored and recycled properly.", "Keep it separate from solvents and antifreeze so it can be recycled."],
  ["MSDS", "The old name for a Safety Data Sheet.", "Same idea; the 16-section SDS replaced it in 2012."],
  ["Hazard Communication (HazCom)", "OSHA's right-to-know rule, 29 CFR 1910.1200.", "Labels, SDSs and training."],
  ["Right to know", "Your right to know the hazards of the chemicals you work with.", "Ask for the SDS any time."],
  ["Written hazcom program", "The shop's written plan for labels, SDSs, training and the chemical list.", "Know where yours is kept."],
  ["Chemical inventory", "The list of hazardous chemicals in the shop.", "Each one needs an SDS."],
  ["SDS Section 1: Identification", "Product name, supplier and emergency phone number.", "First, make sure you have the right SDS."],
  ["SDS Section 2: Hazards", "Hazard class, signal word, pictograms and hazard statements.", "Read this before the first use."],
  ["SDS Section 3: Composition", "The ingredients.", "Trade secrets can be withheld; hazards can't."],
  ["SDS Section 4: First aid", "What to do for eye, skin, breathing or swallowing exposure.", "Read it before an accident, not after."],
  ["SDS Section 5: Firefighting", "Which extinguishers work, and special fire hazards.", "Some chemicals react badly with water."],
  ["SDS Section 6: Accidental release", "How to contain and clean up a spill.", "Keep the right spill kit ready."],
  ["SDS Section 7: Handling and storage", "Safe handling, and what to store it away from.", "Keep incompatible chemicals apart."],
  ["SDS Section 8: Exposure controls / PPE", "Exposure limits, ventilation and protective gear.", "Tells you which gloves and respirator to use."],
  ["SDS Section 9: Physical properties", "Flash point, boiling point, appearance and odor.", "A low flash point means a high fire risk."],
  ["SDS Section 10: Stability and reactivity", "What it reacts with, and conditions to avoid.", "Bleach plus ammonia is the classic bad mix."],
  ["SDS Section 11: Toxicology", "Health effects and symptoms of exposure.", "Covers short- and long-term effects."],
  ["SDS Sections 12–15", "Ecology, disposal, transport and other regulations.", "They're on the SDS, but OSHA doesn't enforce them."],
  ["SDS Section 16: Other information", "The date the SDS was prepared or last revised.", "Make sure your copy is current."],
  ["Signal word", "Danger (more severe) or Warning (less severe).", "Only one appears on a label."],
  ["Hazard statement", "A set phrase describing the hazard, like \"Causes skin burns.\"", "The wording is the same from every maker."],
  ["Precautionary statement", "How to prevent, respond to, store and dispose safely.", "Example: \"Wear protective gloves.\""],
  ["Pictogram", "A hazard symbol inside a red-bordered diamond.", "OSHA requires 8 of the 9 GHS symbols."],
  ["Flame pictogram", "Flammable.", "Brake cleaner, gasoline and many aerosols."],
  ["Corrosion pictogram", "Burns skin and eats metal.", "Battery acid."],
  ["Gas cylinder pictogram", "Gas under pressure.", "Refrigerant and welding tanks."],
  ["Skull and crossbones", "Acute toxicity.", "Small amounts can be deadly."],
  ["Exclamation mark", "Irritants and less severe hazards.", "Many cleaners and coolants."],
  ["Health hazard pictogram", "Cancer, organ damage or breathing sensitizers.", "Long-term effects; follow the PPE closely."],
  ["Flame over circle", "Oxidizer.", "Makes fires burn hotter and faster."],
  ["Exploding bomb", "Explosive or self-reactive.", "Handle with extreme care."],
  ["GHS", "The Globally Harmonized System for classifying and labeling chemicals.", "OSHA's HazCom rule follows it."],
  ["Secondary container label", "A label on a bottle or can you filled from the original.", "It must name the product and its hazards."],
  ["PEL", "Permissible exposure limit: the legal OSHA limit in the air.", "Usually an 8-hour average."],
  ["TWA", "Time-weighted average exposure over 8 hours.", "Short spikes are covered by short-term or ceiling limits."],
  ["Flash point", "The lowest temperature where a liquid's vapor can ignite.", "Gasoline's is far below freezing."],
  ["Incompatible chemicals", "Chemicals that react dangerously together.", "Check SDS Sections 7 and 10."],
  ["NFPA diamond", "The blue, red, yellow and white diamond for responders, rated 0–4.", "In NFPA, 4 is worst; in GHS, Category 1 is worst."],
  ["Used oil container", "A closed container labeled \"Used Oil.\"", "Never mix in solvents or coolant."],
  ["OSHA 1910.1200", "The Hazard Communication Standard.", "Gives workers the right to know chemical hazards."],
  ["GHS label elements", "Product name, pictograms, signal word, hazard and precaution statements, supplier.", "Every shipped container label has them."],
  ["Supplier identification", "Name and contact info of the maker or importer.", "Call them for more info."],
  ["Danger vs Warning", "Danger is for the more severe hazards.", "Warning is for less severe ones."],
  ["Hazard class", "The type of hazard, like flammable or toxic.", "Shown on the SDS."],
  ["Hazard category", "How severe the hazard is within a class.", "Category 1 is the most severe."],
  ["HMIS label", "A colored bar label some shops use.", "Not the same as GHS but still common."],
  ["Workplace labeling", "Labels on shop containers.", "Must give enough hazard info."],
  ["Unlabeled container", "A container with no label.", "Don't use it; label it or dispose of it safely."],
  ["Portable container exemption", "A container for immediate use by one person in one shift.", "Doesn't need a label if used right away by that person."],
  ["SDS access", "Workers must get SDSs during their shift.", "Binder or computer, as long as it's always available."],
  ["SDS in a different language", "SDSs must be in English; others can be added.", "Ask if you need it in another language."],
  ["Hazcom training topics", "Hazards, labels, SDSs and protective measures.", "Training when hired and when new hazards come in."],
  ["New chemical in the shop", "A product the shop hasn't used before.", "Get its SDS before use."],
  ["Trade secret", "Secret ingredients a maker can hold back.", "Medical staff can still get the info when needed."],
  ["Carcinogen", "A substance that can cause cancer.", "Shown with the health hazard pictogram."],
  ["Acute toxicity", "Harm from a single exposure.", "Skull and crossbones means severe acute toxicity."],
  ["Chronic exposure", "Harm from long-term exposure.", "Small exposures add up over years."],
  ["Routes of exposure", "Breathing, skin, eyes and swallowing.", "Block all four."],
  ["Inhalation hazard", "Breathing in vapors or dust.", "Ventilation first, then respirators."],
  ["Skin absorption", "Chemicals entering through skin.", "Gloves and sleeves help."],
  ["Ingestion", "Swallowing a chemical.", "Don't eat or drink in the work area; wash hands."],
  ["Sensitizer", "A chemical that can cause allergies over time.", "Isocyanates in paint are a common example."],
  ["Irritant", "Causes redness or irritation.", "The exclamation mark pictogram."],
  ["Corrosive", "Destroys skin or metal.", "Battery acid is corrosive."],
  ["Oxidizer", "Makes other materials burn more easily.", "Keep away from fuels."],
  ["Compressed gas", "Gas stored under pressure.", "Secure cylinders upright."],
  ["Reactive", "A chemical that can react dangerously.", "See SDS Section 10."],
  ["pH", "How acidic or basic something is.", "Very low or very high pH is corrosive."],
  ["Vapor pressure", "How easily a liquid turns to vapor.", "High vapor pressure = more fumes."],
  ["Evaporation rate", "How fast a liquid evaporates.", "Fast evaporation fills the air faster."],
  ["Odor threshold", "The level where you can smell something.", "Some dangerous gases have no smell."],
  ["IDLH", "Immediately dangerous to life or health.", "A level that can kill or disable quickly."],
  ["STEL", "Short-term exposure limit, usually 15 minutes.", "Even short spikes can be harmful."],
  ["Ceiling limit", "A level never to be exceeded.", "Some chemicals have one."],
  ["Action level", "A level that triggers monitoring or medical checks.", "Usually half the PEL for many substances."],
  ["Exposure monitoring", "Measuring what workers breathe.", "Done for some chemicals by rule."],
  ["Aerosol cans", "Pressurized spray cans.", "Don't puncture or heat; dispose properly."],
  ["Mixing chemicals", "Combining products.", "Never mix cleaners; some make toxic gas."],
  ["Chemical storage by class", "Store acids away from bases and flammables away from oxidizers.", "Check SDS Section 7."]
],
F: [
  ["Fire extinguisher class", "The type of fire an extinguisher is rated for: A ordinary combustibles, B flammable liquids, C electrical.", "An ABC extinguisher covers most shop fires. Know where the nearest one is."],
  ["PASS", "How to use an extinguisher: Pull the pin, Aim at the base, Squeeze, Sweep side to side.", "Aim at the base of the fire, not the flames."],
  ["Fire triangle", "The three things a fire needs: heat, fuel and oxygen.", "Remove any one and the fire goes out."],
  ["Fire tetrahedron", "The fire triangle plus the chemical chain reaction that keeps burning going.", "Dry chemical agents work by breaking that chain."],
  ["Class A fire", "Ordinary combustibles: wood, paper, cloth, rubber, some plastics.", "Water and ABC extinguishers both work."],
  ["Class B fire", "Flammable liquids and gases: gasoline, oil, solvents, propane.", "No water; it spreads burning liquid."],
  ["Class C fire", "Fire in energized electrical equipment.", "Once the power is off, it becomes a Class A or B fire."],
  ["Class D fire", "Burning metals like magnesium, sodium or lithium metal.", "Needs a special Class D agent."],
  ["Class K fire", "Cooking oils and fats.", "Uses a wet chemical agent; rare in auto shops."],
  ["ABC extinguisher", "Dry chemical extinguisher rated for Class A, B and C fires.", "The most common shop extinguisher."],
  ["CO2 extinguisher", "Smothers B and C fires with carbon dioxide gas and leaves no residue.", "The horn gets ice cold. Hold the handle."],
  ["Clean agent", "A gas or vapor extinguisher, like Halotron, that leaves nothing behind.", "Good near electronics and scan tools."],
  ["Extinguisher gauge", "The dial that shows whether the extinguisher is charged.", "Needle in the green. Report anything else."],
  ["Monthly extinguisher check", "A quick look each month that it's in place, charged, sealed and undamaged.", "OSHA 1910.157 requires it."],
  ["Annual extinguisher service", "A yearly maintenance check by a qualified person, with the date recorded.", "Look for the service tag."],
  ["Hydrostatic test", "A pressure test of the extinguisher shell every 5 or 12 years, depending on type.", "CO2 units are every 5 years."],
  ["Flammable liquid", "A liquid that gives off enough vapor to catch fire easily at normal temperatures.", "Gasoline, brake cleaner, many solvents."],
  ["Vapor density", "How heavy a vapor is compared with air.", "Gasoline vapor is heavier, so it flows along the floor."],
  ["Ignition source", "Anything that can light vapors: sparks, flames, hot surfaces, static, bulbs.", "Pilot lights and grinders count."],
  ["Safety can", "An approved metal or plastic can, 5 gallons or less, with a spring-closing lid.", "Red is usually gasoline; yellow, diesel."],
  ["Flame arrester", "A screen in a safety can's spout that stops flame from getting inside.", "Don't remove it to pour faster."],
  ["Flammable cabinet", "A double-walled cabinet labeled 'Flammable — Keep Fire Away.'", "Keep doors closed. 60 gallons max of most flammables."],
  ["Oily waste can", "A metal can with a self-closing lid for oily or solvent rags.", "Empty it every day."],
  ["Spontaneous combustion", "A fire that starts on its own as oily materials heat up.", "Linseed oil and stain rags are the worst."],
  ["Bonding", "Connecting two containers with a wire so no spark can jump between them.", "Do it before pouring from a drum."],
  ["Grounding", "Connecting a container to earth to drain static electricity.", "Drums used for dispensing should be grounded."],
  ["Static spark", "A spark from built-up static charge that can light fuel vapor.", "Fill gas cans on the ground, not in a truck bed."],
  ["Hot work", "Any work that makes sparks, flame or heat: welding, cutting, grinding, brazing.", "Clear combustibles before you start."],
  ["Hot work permit", "A written OK for hot work after the area is checked.", "Many shops require one outside the weld bay."],
  ["Fire watch", "A trained person with an extinguisher who watches for fire during and after hot work.", "Stays at least 30 minutes after the work ends."],
  ["35-foot rule", "Move combustibles at least 35 feet from hot work, or protect them.", "From OSHA 1910.252."],
  ["Fuel caddy", "A closed, grounded container for draining fuel tanks.", "Never drain fuel into an open pan."],
  ["Fusible link", "A metal link that melts at a set temperature to trigger a safety device.", "Found on parts washer lids and fire doors."],
  ["Thermal runaway", "A chain reaction where a lithium cell overheats and spreads to the next.", "Hard to stop and can reignite hours later."],
  ["Flashback arrestor", "A valve that stops flame from traveling back into torch hoses and cylinders.", "Fit them at the regulators."],
  ["Pull station", "The handle on the wall that sets off the building fire alarm.", "Know where the nearest one is."],
  ["LEL", "Lower explosive limit: the least vapor in air that can burn.", "Gasoline's is only about 1.4%."],
  ["Auto-ignition temperature", "The temperature where vapor lights with no spark or flame.", "Hot exhaust parts can be hotter than that."],
  ["Smoldering", "Burning slowly with heat and smoke but no flame.", "Why the fire watch stays after the welding stops."],
  ["Fire blanket", "A fire-resistant sheet used to smother a small fire or a person's burning clothes.", "Stop, drop and roll, then wrap."],
  ["NFPA 10", "The standard for portable fire extinguishers.", "Covers placement, inspection and service."],
  ["OSHA 1910.157", "The OSHA rule for portable extinguishers.", "Requires monthly checks and annual maintenance."],
  ["Class A travel distance", "Max walk to a Class A extinguisher: 75 feet.", "Keep paths to extinguishers clear."],
  ["Class B travel distance", "Max walk to a Class B extinguisher is generally 50 feet.", "Shorter for bigger hazards; check the rules."],
  ["Extinguisher mounting", "Mounted on hangers or in cabinets.", "Not on the floor where they get hit."],
  ["Extinguisher signs", "Signs that show where extinguishers are.", "Visible from a distance."],
  ["Extinguisher training", "Training on how to use extinguishers.", "Required yearly if workers are expected to use them."],
  ["Fight or flee", "Only fight small fires with a clear exit.", "If in doubt, get out."],
  ["Back to the exit", "Keep the exit behind you when using an extinguisher.", "Never let fire get between you and the way out."],
  ["Extinguisher reach", "How far the spray goes.", "Start back 6–10 feet for most portables."],
  ["Discharge time", "How long an extinguisher sprays.", "Often only 10–20 seconds."],
  ["Recharge after use", "Any use means service.", "Even a short spray."],
  ["Tamper seal", "A plastic seal on the pin.", "Broken seal = check or service it."],
  ["Inspection tag", "Tag showing service dates.", "Initial and date monthly checks."],
  ["Water extinguisher", "For Class A only.", "Never on electrical or grease fires."],
  ["Wet chemical extinguisher", "For cooking oil (Class K).", "Used in kitchens."],
  ["Dry chemical residue", "Powder left after use.", "Corrosive to electronics; clean it up."],
  ["CO2 cold burn", "CO2 horn gets extremely cold.", "Hold the handle, not the horn."],
  ["Fire in an engine bay", "Don't open the hood wide.", "Opening feeds air; crack it and aim through the gap."],
  ["Vehicle fire", "Fuel, plastics and tires burn fast.", "Get away and call 911."],
  ["EV fire", "Battery fires are hard to put out.", "Leave it to firefighters; tell them it's an EV."],
  ["Gasoline vapors", "Vapors heavier than air that spread along floors.", "Keep ignition sources away from drains and pits."],
  ["Fuel drain safety", "Draining fuel into approved containers.", "Ground and bond, no sparks."],
  ["Drop light danger", "Incandescent drop lights can break and ignite fuel.", "Use enclosed LED work lights."],
  ["Static-safe fuel container", "Approved containers that limit static.", "Don't fill containers in a truck bed."],
  ["Flammable liquid limits", "OSHA limits how much can be outside cabinets.", "Keep only what you need for the day."],
  ["Self-closing lid", "A lid that closes automatically.", "On safety cans and oily rag cans."],
  ["Oily rag disposal", "Rags with oil or solvent can self-heat.", "Use a metal can with a lid; empty daily."],
  ["Paint and thinner storage", "Store in flammable cabinets.", "Keep lids tight."],
  ["Battery charging fire risk", "Hydrogen and sparks.", "Ventilate and keep sparks away."],
  ["Lithium battery fire", "Phones, tools and packs can burn.", "Don't charge damaged lithium batteries."],
  ["Welding near fuel", "Welding near tanks or lines.", "Remove or shield fuel first."],
  ["Hot work area", "Clear 35 feet of combustibles or shield them.", "Fire watch stays after the work."],
  ["Spark containment", "Blankets and screens to stop sparks.", "Cover drains and gaps."],
  ["Electrical fire", "Fire in wiring or equipment.", "Cut power if safe; use a Class C rated extinguisher."],
  ["Overloaded outlet", "Too many devices on one outlet.", "A common fire cause."],
  ["Extension cord use", "Temporary use only.", "Don't run them under doors or through walls."],
  ["Smoking rules", "No smoking in work areas.", "Use designated areas only."],
  ["Fire alarm", "System that warns everyone.", "Know how to pull it."],
  ["Fire drill", "Practicing evacuation.", "Know your exit and assembly point."]
],
L: [
  ["Jack stand", "A fixed-height support placed under a lift point to hold a raised vehicle.", "Never work under a car held only by a jack. Jacks lift; stands hold."],
  ["Lift point", "The spot on the frame or pinch weld the maker says is safe to lift or support the vehicle.", "Check the service info or the lift-point chart; hybrids and EVs often have special ones."],
  ["Wheel chock", "A wedge placed against a tire to stop the vehicle from rolling.", "Chock the wheels that stay on the ground whenever one end is in the air."],
  ["Two-post lift", "A lift with two columns and arms that pick the car up by its frame or pinch welds.", "Check the arm locks engage and the car is balanced before raising it high."],
  ["Lift safety lock", "The mechanical catch that holds the lift up even if hydraulic pressure is lost.", "Lower onto the locks before working underneath."],
  ["Floor jack", "A rolling hydraulic jack used to lift one corner or end of a vehicle.", "It lifts. Stands hold."],
  ["Bottle jack", "A compact upright hydraulic jack with a small base.", "Tips easily; use on flat, hard ground."],
  ["Scissor jack", "The small crank jack that comes with the spare tire.", "Roadside use only. Never go under the car."],
  ["Rated capacity", "The most weight a lift, jack or stand is built to hold.", "Check the label before every lift."],
  ["Four-post lift", "A drive-on lift that holds the car by its tires on two runways.", "Chock the wheels and use the locks."],
  ["Scissor lift", "A low-rise or mid-rise lift with crossing arms that open like scissors.", "Check pad placement on every lift."],
  ["In-ground lift", "A lift with its hydraulic cylinder buried in the floor.", "Leaks can go unseen; report any drift."],
  ["Symmetric lift", "A two-post lift that centers the car between the posts, with equal arms.", "Common for trucks and long vehicles."],
  ["Asymmetric lift", "A two-post lift with shorter front arms that sets the car farther back.", "Lets doors open; follow the spotting guide."],
  ["Center of gravity", "The balance point of the vehicle's weight.", "It moves when you remove heavy parts."],
  ["Arm restraint", "A lock that keeps a lift arm from swinging once it's loaded.", "Make sure it engages before raising."],
  ["Lift pad", "The rubber pad on a lift arm that touches the lift point.", "Replace torn pads."],
  ["Height adapter", "An approved extension that raises a pad to reach a high lift point.", "Use only the maker's adapters. No stacking blocks."],
  ["Pinch weld", "The welded seam under a unibody car's rocker panel.", "A common lift point; use a slotted pad to avoid crushing it."],
  ["Frame rail", "The main beam of a body-on-frame vehicle.", "Lift and support trucks here, per the service info."],
  ["Shake test", "Raising a car a few inches and rocking it to check it's stable on the pads.", "If anything moves, lower and reset."],
  ["ALI gold label", "The Automotive Lift Institute label showing a lift is certified to the safety standard.", "Look for it on new lifts."],
  ["ANSI/ALI ALOIM", "The standard for lift operation, inspection and maintenance.", "It calls for yearly inspections by a qualified inspector."],
  ["Annual lift inspection", "A yearly check of a lift by a qualified lift inspector.", "Keep the report on file."],
  ["Daily lift check", "A quick look at locks, arms, pads, cables and leaks before use.", "Tag out a lift that fails."],
  ["Lock release", "The handle or button that frees the safety locks so the lift can go down.", "Raise slightly off the locks first."],
  ["Tall safety stand", "A tall stand placed under a car on a lift to add support.", "Use it when pulling engines, transmissions or axles."],
  ["Transmission jack", "A jack with a saddle and chains to hold and lower a transmission.", "Chain the load before moving it."],
  ["Engine hoist", "A rolling crane used to lift an engine out of the car.", "Capacity drops as the boom extends."],
  ["Load leveler", "A bar between the hoist hook and the engine that adjusts the tilt.", "Helps line the engine up for install."],
  ["Engine support bar", "A bar across the fenders that holds the engine from above.", "Used when a mount or subframe comes out."],
  ["Rolling jack", "A jack that rides on a four-post lift to raise the wheels off the runways.", "Also called a bridge jack."],
  ["Runway", "The long platforms on a four-post lift that the tires sit on.", "Keep them clear of tools and fluid."],
  ["Approach ramp", "The short ramp used to drive onto a four-post lift.", "Make sure it's in place before driving on."],
  ["Out-of-service tag", "A tag that says equipment is unsafe and must not be used.", "Only remove it after repair and checks."],
  ["Jack mode", "A setting that stops air suspension from self-leveling while lifted.", "Turn it on before lifting cars with air suspension."],
  ["EV lift points", "Maker-approved lift spots that keep pads off the battery pack.", "A crushed pack can catch fire later."],
  ["GVWR", "Gross vehicle weight rating: the most the loaded vehicle may weigh.", "It's on the door jamb sticker."],
  ["Creeper", "A low rolling board for working under a vehicle.", "Stand it up when you're done; it's a trip hazard."],
  ["Overhead clearance", "The room between the top of a raised vehicle and the ceiling.", "Watch roof racks and tall vans."],
  ["Lift operator training", "Training to use a lift safely.", "ALI and the lift maker provide materials."],
  ["Lift capacity label", "The max weight the lift can hold.", "Check vehicle weight first."],
  ["Vehicle weight check", "Finding the car's weight on the door label or service info.", "Trucks and EVs can be heavy."],
  ["Front-heavy vehicles", "Most weight over the front axle.", "Position arms to balance."],
  ["Rear-heavy vehicles", "Trucks with beds, vans with loads.", "May tip backward if positioned wrong."],
  ["Removing heavy parts", "Removing engines or axles shifts balance.", "Use tall stands to support the car."],
  ["Lift arm locks", "Locks that keep arms from swinging.", "Check they engage before lifting."],
  ["Lift raising check", "Raise a few inches, stop, check contact.", "Shake test before going higher."],
  ["Lower onto locks", "Set the lift on the mechanical locks before working.", "Never work under a lift held only by hydraulics."],
  ["Lowering check", "Clear tools, stands and people first.", "Lower slowly."],
  ["Lift cables", "Steel cables that move lift carriages.", "Inspect for broken strands."],
  ["Lift pulleys", "Guide the cables.", "Look for wear and noise."],
  ["Lift hydraulic leaks", "Fluid leaking from lift cylinders.", "Report and tag out."],
  ["Lift anchor bolts", "Bolts holding the lift to the floor.", "Check they're tight."],
  ["Lift floor requirements", "Concrete thickness and strength rules.", "Set by the lift maker."],
  ["Overhead shutoff bar", "Stops the lift if the car hits it.", "Don't remove or bypass it."],
  ["Lift controls", "Up, down and lock release.", "Know them before you operate."],
  ["Lift power unit", "Motor and pump that raise the lift.", "Keep the area clear."],
  ["Wheel-free jacks", "Jacks on four-post lifts that lift the wheels off.", "Follow capacity limits."],
  ["Drive-on lifts", "Lifts with runways.", "Chock wheels and set the parking brake."],
  ["Low-rise lift", "A short lift for tires and body work.", "Different safety steps; read the manual."],
  ["Mobile column lifts", "Portable lifts that grab each wheel.", "For heavy trucks; all columns must sync."],
  ["Jack placement", "Place jacks on lift points only.", "Not on oil pans or suspension arms unless allowed."],
  ["Jack saddle", "The top of the jack that contacts the car.", "Use the right pad to avoid damage."],
  ["Jack stand height lock", "The pin or ratchet that holds height.", "Make sure it's fully engaged."],
  ["Jack stand pairs", "Use stands in pairs on a level surface.", "Never on dirt or gravel."],
  ["Jack stand capacity", "Rated per pair.", "Stay under the rating."],
  ["Lowering onto stands", "Lower the jack slowly onto stands.", "Check the car is stable before going under."],
  ["Never under a jack", "Never work under a car held only by a jack.", "Jacks can drop without warning."],
  ["Blocks and bricks", "Never use them as supports.", "They can crumble."],
  ["Hydraulic jack maintenance", "Check fluid and seals.", "A jack that sinks is unsafe."],
  ["Jack inspection", "Check for cracks and leaks before use.", "Tag out damaged jacks."],
  ["Transmission jack chains", "Chains that secure the transmission.", "Always use them."],
  ["Engine hoist boom", "Capacity drops as the boom extends.", "Check the label for each position."],
  ["Lifting chain", "Chain used to lift engines.", "Rated chain only; check hooks."],
  ["Load leveler use", "Balances an engine on the hoist.", "Adjust before lifting high."],
  ["Lift in an EV shop", "EV packs are heavy and low.", "Use the maker's lift points."],
  ["Battery table", "A table for removing EV packs.", "Rated for the pack weight."],
  ["Overhead hazards", "Lifted cars and hoists above you.", "Wear a bump cap; watch your head."],
  ["Tagged-out lift", "A lift marked out of service.", "Don't use it until repaired."]
],
T: [
  ["Pinch point", "A spot where moving parts meet and can trap fingers or hands.", "Belts, pulleys, fans and lift arms. Keep hands clear when the engine runs."],
  ["Tool rest", "The ledge on a bench grinder that supports the part.", "Keep it within 1/8 inch of the wheel."],
  ["Tongue guard", "The top guard on a bench grinder, just above the wheel.", "Keep it within 1/4 inch of the wheel."],
  ["Ring test", "Tapping a vitrified wheel to listen for a clear ring before mounting.", "A dull thud can mean a crack."],
  ["Max RPM rating", "The fastest a wheel or disc is safe to spin.", "It must be at or above the tool's speed."],
  ["Wheel guard", "The cover around a grinding wheel or disc.", "It catches pieces if the wheel breaks."],
  ["Angle grinder", "A handheld grinder with a disc at a right angle to the motor.", "Two hands, side handle on, guard in place."],
  ["Cut-off wheel", "A thin abrasive disc for cutting metal.", "Cut with the edge, never the side."],
  ["Wire wheel", "A spinning brush of steel wires for rust and paint.", "Wires fly off. Face shield and sleeves."],
  ["Mushroomed head", "The spread, cracked top of a struck chisel or punch.", "Grind it smooth or replace the tool."],
  ["Cheater bar", "A pipe slipped over a handle for extra leverage.", "Breaks ratchets and causes slips. Use a breaker bar."],
  ["Pull, don't push", "Pull wrenches toward you so a slip doesn't drive your hand into metal.", "If you must push, use an open palm."],
  ["Dead-blow hammer", "A hammer filled with shot so it doesn't bounce back.", "Gentler on parts than a steel hammer."],
  ["Impact socket", "A thick black socket made for impact tools.", "Chrome hand sockets can shatter on an impact gun."],
  ["Double insulated", "A tool built with extra insulation, marked with a square inside a square.", "It doesn't need a ground prong."],
  ["90 psi", "The typical working pressure for air tools.", "Set the regulator; more isn't better."],
  ["30 psi rule", "Air used for cleaning must be under 30 psi with chip guarding.", "OSHA 1910.242(b)."],
  ["Chip guarding", "A nozzle shield or barrier that stops chips from flying back at you.", "Many safety nozzles have it built in."],
  ["Whip check", "A cable that holds an air hose if a fitting lets go.", "Used on larger hoses and connections."],
  ["Quick coupler", "The snap-together fitting between an air hose and a tool.", "Hold the hose when you disconnect it."],
  ["Hydraulic press", "A shop press that pushes bearings and bushings in or out.", "Use the shield and stand out of line."],
  ["Press shield", "The guard on a hydraulic press that catches flying parts.", "Keep it closed while pressing."],
  ["Spring compressor", "A tool that squeezes a coil spring so a strut can be taken apart.", "Check it for damage before each use."],
  ["Stored energy", "Energy held in springs, air, fluid or electricity that can release suddenly.", "Release or block it before working."],
  ["Tire changer", "A machine that mounts and removes tires from wheels.", "Keep fingers away from the bead."],
  ["Bead seating limit", "Don't go over 40 psi to seat a passenger tire's beads.", "If it won't seat, deflate and find out why."],
  ["Inflation cage", "A steel cage that holds a tire and wheel during inflation.", "Required for multi-piece rims (OSHA 1910.177)."],
  ["Clip-on chuck", "An air chuck that locks onto the valve stem so you can stand back.", "Use with a long hose and an inline valve."],
  ["Trajectory zone", "The path parts would fly if a tire or rim blew apart.", "Stand outside it, usually off to the side."],
  ["Multi-piece rim", "A truck or equipment wheel with a separate lock ring.", "Lock rings can fly off with deadly force."],
  ["Balancer hood", "The cover on a wheel balancer that drops over the spinning wheel.", "Hood down before spinning."],
  ["Brake lathe", "A machine that resurfaces rotors and drums.", "No loose clothing; keep the chip shield on."],
  ["Parts washer", "A tank of solvent or detergent for cleaning parts.", "Wear gloves and keep the lid ready to close."],
  ["Injection injury", "Fluid or air forced under the skin by high pressure.", "Looks small, but go to the ER right away."],
  ["Oxy-acetylene", "A torch that burns acetylene with pure oxygen for heating, cutting and brazing.", "Both cylinders chained upright."],
  ["15 psi acetylene limit", "Acetylene must never be used above 15 psi.", "From OSHA 1910.253."],
  ["Spark lighter", "A flint striker used to light a torch.", "Never use a cigarette lighter."],
  ["Cylinder cap", "The screw-on cap that protects a gas cylinder's valve.", "Keep it on whenever the cylinder is moved or stored."],
  ["Welder's flash", "A painful eye burn from welding UV light.", "Wear the right helmet shade; warn others nearby."],
  ["Three points of contact", "Two hands and a foot, or two feet and a hand, on a ladder at all times.", "Don't carry tools in your hands while climbing."],
  ["OSHA 1910.242", "The rule for hand and portable power tools.", "Employers must keep tools safe."],
  ["Tool inspection", "Checking tools before use.", "Pull damaged tools from service."],
  ["Wrong tool for the job", "Using a tool in a way it wasn't made for.", "Screwdrivers aren't pry bars."],
  ["Wrench slip", "A wrench slipping off a bolt.", "Pull toward you and use six-point sockets."],
  ["Rounded fasteners", "Damaged bolt heads.", "Use the right size and extractor sockets."],
  ["Hand tool maintenance", "Clean, sharp, undamaged tools.", "Dull tools take more force and slip."],
  ["Impact wrench safety", "High-torque air or electric guns.", "Use impact sockets and hold firmly."],
  ["Chrome sockets on impacts", "Regular sockets can shatter.", "Use only impact-rated sockets."],
  ["Air tool oiling", "A few drops of oil keeps air tools working.", "Follow the tool maker."],
  ["Air hose inspection", "Check hoses for cracks and leaks.", "Replace damaged hoses."],
  ["Air pressure regulator", "Sets tool air pressure.", "Use the tool's rated pressure."],
  ["Never point air at people", "Compressed air can enter skin or eyes.", "Never use it to clean clothes on your body."],
  ["Electric tool cords", "Check for cuts and missing ground pins.", "Don't carry tools by the cord."],
  ["Cordless battery safety", "Lithium packs can overheat.", "Use the maker's charger."],
  ["Drill bind", "A drill bit catching and twisting the drill.", "Hold firmly; use the side handle."],
  ["Grinder kickback", "A grinder jumping when the wheel catches.", "Use both hands and keep guards on."],
  ["Wheel speed rating", "The max RPM for a grinding wheel.", "Must be at least the tool's speed."],
  ["Wheel inspection", "Check wheels for cracks before mounting.", "A cracked wheel can explode."],
  ["Bench grinder guard", "Covers most of the wheel.", "Keep the tongue guard adjusted."],
  ["Grinding aluminum", "Aluminum can clog a wheel.", "Use the right wheel for the metal."],
  ["Sparks and clothing", "Grinding sparks burn clothes.", "Wear cotton or FR clothing."],
  ["Cutting tool guards", "Guards on saws and cutters.", "Never remove them."],
  ["Hacksaw safety", "Blades can snap.", "Teeth face forward; tight blade."],
  ["Chisel safety", "Use eye protection and a sharp chisel.", "Dress mushroomed heads."],
  ["Torch heat", "Oxy-acetylene torches cut and heat metal.", "Keep fuel lines and plastic away."],
  ["Torch checks", "Check hoses and fittings for leaks.", "Use soapy water, not a flame."],
  ["Cylinder storage", "Oxygen and fuel cylinders stored apart.", "20 feet or a fire wall between them."],
  ["Cylinder securing", "Chain cylinders upright.", "A falling cylinder can become a rocket if the valve breaks."],
  ["Welding curtain", "A screen that blocks arc light.", "Protects others nearby."],
  ["Welder grounding", "Clamp ground near the weld.", "Disconnect the car battery as the maker says."],
  ["Plasma cutter", "Cuts metal with an electric arc and air.", "Eye protection and fire safety needed."],
  ["Press safety", "Hydraulic presses can make huge force.", "Use guards and stand to the side."],
  ["Bearing pulling", "Using pullers on bearings and gears.", "Parts can fly when they release."],
  ["Spring compressor safety", "Coil springs store energy.", "Use the right tool and keep clear."],
  ["Tire inflation over 40 psi", "Seating beads above about 40 psi is dangerous.", "Use a cage and follow rim and tire limits."],
  ["Rim wheel (1910.177)", "OSHA rule for servicing rim wheels.", "Requires training, cages and clip-on chucks for some work."],
  ["Wheel balancer safety", "Spinning wheels on a balancer.", "Lower the hood and stay clear."],
  ["Tire changer safety", "Bead breakers and turntables can pinch.", "Keep hands clear of the bead and clamps."],
  ["Parts washer safety", "Solvent tanks can catch fire.", "Close the lid when not in use."],
  ["Housekeeping", "Clean floors and organized tools.", "Prevents slips and lost tools."]
],
A: [
  ["Carbon monoxide (CO)", "A colorless, odorless, deadly gas in engine exhaust.", "Hook up the exhaust hose any time an engine runs indoors."],
  ["Brake dust", "Fine dust from brake pads and shoes that you shouldn't breathe or blow around.", "Use a brake washer or wet method, never compressed air."],
  ["CO PEL", "OSHA's carbon monoxide limit: 50 ppm averaged over 8 hours.", "NIOSH recommends 35 ppm."],
  ["NIOSH REL", "The exposure level NIOSH recommends, often stricter than OSHA's.", "For CO it's 35 ppm."],
  ["CO poisoning signs", "Headache, dizziness, nausea, confusion and tiredness.", "If several people feel sick, suspect CO."],
  ["Exhaust extraction", "Hoses and fans that carry engine exhaust outside.", "Hook it up before you start the engine."],
  ["Local exhaust ventilation", "Capturing fumes right where they're made.", "Better than fans that only stir the air."],
  ["General ventilation", "Bringing fresh air into the whole shop to dilute fumes.", "Helps, but doesn't replace local exhaust."],
  ["Hierarchy of controls", "Eliminate, substitute, engineer, set rules, then PPE.", "Start at the top of the list."],
  ["Engineering control", "Equipment that removes or blocks a hazard, like extraction or guards.", "It works without anyone remembering to wear it."],
  ["Diesel exhaust", "Exhaust with soot particles and gases that IARC lists as a carcinogen.", "Use extraction on every diesel."],
  ["Diesel particulate", "The fine soot in diesel exhaust.", "Small enough to go deep into the lungs."],
  ["Asbestos", "A mineral fiber once common in brakes, clutches and gaskets that causes lung disease and cancer.", "Never blow or dry brush brake dust."],
  ["HEPA vacuum", "A vacuum with a high-efficiency filter that traps very fine particles.", "A regular shop vac can blow dust back out."],
  ["Wet method", "Wetting brake parts to keep dust out of the air.", "Use a brake washer or low-pressure spray."],
  ["Negative-pressure enclosure", "A sealed box with a HEPA vacuum that surrounds the brake while you clean.", "One of OSHA's approved brake methods."],
  ["Clutch dust", "Dust from clutch linings that can contain asbestos.", "Handle it like brake dust."],
  ["Respirator", "A mask that filters the air or supplies clean air.", "Needs a medical check and fit test if tight-fitting."],
  ["Fit test", "A test that the respirator seals to your face.", "Required before use and every year after."],
  ["N95", "A filtering mask that stops at least 95% of airborne particles.", "Doesn't stop vapors or gases."],
  ["Organic vapor cartridge", "A respirator cartridge that absorbs solvent and paint vapors.", "Change it on a schedule, not by smell."],
  ["Isocyanates", "Chemicals in 2K paints and clears that can cause asthma.", "Use a booth and proper air supply."],
  ["Spray booth", "An enclosed area with filtered airflow for painting.", "Keep doors closed and filters changed."],
  ["Welding fumes", "Tiny metal particles and gases from welding.", "Use extraction and keep out of the plume."],
  ["Metal fume fever", "Flu-like illness from breathing zinc fumes when welding galvanized metal.", "Remove the coating or use extraction."],
  ["Hexavalent chromium", "A toxic form of chromium released when welding stainless steel.", "Known lung carcinogen."],
  ["Phosgene", "A toxic gas formed when chlorinated solvents hit heat or welding arcs.", "Keep chlorinated brake cleaner away from welding."],
  ["Chlorinated brake cleaner", "Brake cleaner with chlorinated solvents; nonflammable but toxic.", "Never use near welding or hot parts."],
  ["Non-chlorinated brake cleaner", "Brake cleaner without chlorine; less toxic but very flammable.", "Keep it away from sparks and heat."],
  ["Benzene", "A cancer-causing chemical in gasoline.", "Don't wash hands in fuel or breathe its vapor."],
  ["Oxygen-deficient air", "Air with less than 19.5% oxygen.", "Can cause collapse with no warning."],
  ["Confined space", "A space with limited entry and exit not meant for people to stay in.", "Pits and tanks can qualify (OSHA 1910.146)."],
  ["Service pit", "A trench in the floor for working under vehicles.", "Heavy vapors collect there; ventilate it."],
  ["R-134a", "The refrigerant used in most cars before about 2015.", "Recover it, never vent it."],
  ["R-1234yf", "The newer, mildly flammable refrigerant in most current cars.", "Needs its own machine and fittings."],
  ["Refrigerant identifier", "A tool that tests what refrigerant is in a system before recovery.", "Protects your machine from contamination."],
  ["Recovery machine", "A machine that pulls refrigerant out of a system for recycling.", "Each refrigerant needs its own machine."],
  ["EPA Section 609", "The Clean Air Act rule requiring certification to service vehicle A/C.", "Required for paid A/C work with any refrigerant."],
  ["Venting ban", "The rule against releasing refrigerant into the air.", "Always recover it with approved equipment."],
  ["Hydrogen fluoride", "A very toxic acid gas made when refrigerant or some seals burn.", "Don't handle fire-damaged parts bare-handed."],
  ["Carbon monoxide detector", "An alarm that measures CO in the air.", "Test it and keep it powered."],
  ["Exhaust adapter", "The end piece that fits the extraction hose over a tailpipe.", "Use one on each tailpipe."],
  ["CO is odorless", "Carbon monoxide has no color or smell.", "You can't tell you're breathing it."],
  ["Running engines indoors", "Engines make CO even when idling.", "Use exhaust hoses every time."],
  ["Catalytic converter and CO", "Converters lower CO but don't remove it all.", "Cold engines make the most CO."],
  ["CO IDLH", "1,200 ppm is immediately dangerous to life.", "Get out and get fresh air."],
  ["CO ceiling (NIOSH)", "NIOSH says never exceed 200 ppm.", "Even short exposures matter."],
  ["Headache and dizziness", "Early signs of CO poisoning.", "Get to fresh air and tell someone."],
  ["Exhaust hose inspection", "Check hoses for holes.", "A leaking hose fills the shop."],
  ["Overhead exhaust reel", "A hose that pulls exhaust outside.", "Clamp it to the tailpipe."],
  ["Dual exhaust", "Two tailpipes need two hoses.", "Cover both."],
  ["Shop fans", "Fans that move air.", "Fans alone don't remove CO; use exhaust extraction."],
  ["Make-up air", "Fresh air brought in to replace exhausted air.", "Needed for extraction to work well."],
  ["Winter ventilation", "Closed doors trap fumes.", "Keep extraction running in cold weather."],
  ["Propane equipment indoors", "Propane forklifts and heaters make CO.", "Maintain and ventilate."],
  ["Diesel exhaust fluid fumes", "Ammonia smell around DEF systems.", "Ventilate the area."],
  ["Asbestos in brakes", "Some older and aftermarket brakes may contain asbestos.", "Treat brake dust as asbestos unless proven otherwise."],
  ["Never blow brake dust", "Compressed air spreads fibers.", "Use wet methods or a HEPA vacuum."],
  ["Low-pressure wet cleaning", "Washing brake parts with a gentle spray.", "OSHA allows it for brake and clutch work."],
  ["Equivalent method (brakes)", "Another brake-dust control OSHA allows if it works as well as the listed methods.", "OSHA 1910.1001 Appendix F; it must be proven, not assumed."],
  ["Asbestos PEL", "0.1 fibers per cubic centimeter of air.", "OSHA 1910.1001."],
  ["Silica dust", "Dust from sanding concrete or some fillers.", "Use wet methods and respirators."],
  ["Body filler dust", "Dust from sanding body filler.", "Use dust extraction and masks."],
  ["Paint fumes", "Solvent vapors from painting.", "Paint only in booths with supplied air if needed."],
  ["Supplied-air respirator", "A respirator with clean air from a hose.", "Used for isocyanate paints."],
  ["Galvanized metal welding", "Zinc coating gives off toxic fumes.", "Ventilate and grind off coating."],
  ["Stainless welding", "Can release hexavalent chromium.", "Use extraction and respirators."],
  ["Brake cleaner and welding", "Chlorinated cleaner near welding can make phosgene.", "Never weld near it."],
  ["Solvent vapors", "Fumes from cleaners and fuels.", "Ventilate and limit use."],
  ["Carb cleaner fumes", "Strong solvents in carb and throttle cleaners.", "Use outside or with ventilation."],
  ["Refrigerant in a pit", "Refrigerant is heavier than air.", "It can push oxygen out of pits."],
  ["Oxygen level", "Normal air is about 20.9% oxygen.", "Below 19.5% is oxygen-deficient."],
  ["Gas detector", "A meter that measures oxygen, CO and other gases.", "Use before entering pits or tanks."],
  ["Fuel tank vapors", "Empty tanks still hold vapors.", "Never weld or cut a fuel tank."],
  ["Battery fumes", "Hydrogen and acid mist from charging.", "Charge in a ventilated area."],
  ["Coolant fumes", "Hot coolant steam can burn.", "Never open a hot cooling system."],
  ["Mold in HVAC", "Mold from evaporators.", "Use a mask when cleaning."],
  ["Dust collection", "Systems that collect dust at the source.", "Empty bags carefully."],
  ["Indoor air monitoring", "Measuring CO and other levels.", "CO alarms help in shops."],
  ["Symptoms list", "Headache, nausea, dizziness, confusion.", "Many fumes cause similar signs."]
],
E: [
  ["Lockout/tagout", "Locking and tagging an energy source off so nobody can turn it on while you work on it.", "Your lock, your key. Nobody removes your lock but you."],
  ["Battery acid", "Sulfuric acid inside lead-acid batteries; it burns skin and eyes.", "Wear glasses and gloves when handling batteries. Baking soda neutralizes spills."],
  ["Electric cooling fan", "A radiator fan that can switch on by itself even with the key off.", "Keep hands out of the fan's path, or unplug it first."],
  ["Airbag (SRS)", "Supplemental Restraint System: the airbags and seat belt pretensioners.", "Disconnect the battery and wait the time in the service info before working near airbags."],
  ["High voltage (HV)", "In vehicles, anything above 60 V DC or 30 V AC.", "Hybrid and EV packs run hundreds of volts."],
  ["Orange cable", "The color code for high-voltage wiring in hybrids and EVs.", "Treat it as live until tested dead."],
  ["Service disconnect", "A plug or switch that breaks the HV battery circuit.", "Remove it and keep it in your pocket."],
  ["HV battery pack", "The large high-voltage battery that powers a hybrid or EV.", "Never pierce, lift under, or open it without training."],
  ["Inverter capacitor", "A part in the inverter that stores charge after the pack is off.", "Wait the listed time, then test."],
  ["Wait time", "The minutes to wait after HV shutdown so stored charge drains.", "Use the number in the service info."],
  ["Class 0 gloves", "Rubber insulating gloves rated 1,000 V AC / 1,500 V DC.", "The usual class for EV work."],
  ["Leather protector", "A leather glove worn over rubber insulating gloves.", "Protects the rubber from cuts; never wear it alone."],
  ["Glove retest", "Electrical testing of insulating gloves every 6 months.", "Check the test date stamped on the cuff."],
  ["Insulated tools", "Hand tools rated and tested for 1,000 V work.", "Inspect for nicks; damaged insulation means discard."],
  ["CAT III meter", "A meter rated to safely measure higher-energy circuits.", "Use CAT III 1,000 V or better on HV systems."],
  ["Live-dead-live", "Test the meter on a live source, test the circuit, then retest the live source.", "Proves a zero reading is real."],
  ["Absence of voltage", "Confirmed by testing that no voltage is present.", "Never assume; always test."],
  ["One-hand rule", "Working with one hand away so current can't cross your chest.", "Rest the other hand on your leg."],
  ["HV barrier", "Cones, chains or signs that mark off an HV work area.", "Keeps untrained people out."],
  ["Rescue hook", "An insulated hook for pulling a person off a live circuit.", "Keep it next to the HV work area."],
  ["Ready mode", "An EV or hybrid that's powered on and can move or start silently.", "Turn it fully off and move the fob away."],
  ["HVIL", "High-voltage interlock loop: a low-voltage circuit that shuts HV off when a connector is opened.", "It's a safety backup, not a replacement for the shutdown steps."],
  ["Arc flash", "An explosive release of energy from an electrical short.", "Causes severe burns and eye damage."],
  ["GFCI", "Ground fault circuit interrupter: cuts power when current leaks to ground.", "Trips at about 5 milliamps; press TEST monthly."],
  ["Ground prong", "The round third prong on a plug that carries fault current away.", "Never cut it off."],
  ["Circuit breaker", "A switch that trips to stop too much current.", "If it keeps tripping, find out why."],
  ["Fuse rating", "The amps a fuse can carry before it blows.", "Always replace with the same rating."],
  ["Working clearance", "Open space kept in front of electrical panels.", "At least 3 feet for most shop panels."],
  ["Zero energy state", "Equipment with every energy source off, released or blocked.", "Verify it before you start."],
  ["Energy-isolating device", "A breaker, switch or valve that cuts off an energy source.", "This is where the lock goes."],
  ["Personal lock", "A lock only you have the key to, used for lockout.", "One person, one lock, one key."],
  ["Hydrogen gas", "An explosive gas that lead-acid batteries give off while charging.", "No sparks or flames near batteries."],
  ["Frozen battery", "A battery with ice inside its cells.", "Never charge or jump it until thawed."],
  ["Memory saver", "A device that keeps power to the car while the battery is out.", "It can keep airbag circuits live."],
  ["Ignition coil", "Makes the high voltage that fires the spark plugs.", "Can deliver tens of thousands of volts."],
  ["HID ballast", "The box that starts and runs xenon headlights with high voltage.", "Unplug before handling."],
  ["ESD strap", "A wrist strap that drains static from your body.", "Wear it when handling modules."],
  ["Megger", "An insulation tester that applies high test voltage.", "Hands off the leads during a test."],
  ["Let-go current", "The current at which muscles lock and you can't let go.", "Only a few hundredths of an amp."],
  ["Jump-start order", "Red dead +, red good +, black good -, black engine ground last.", "The last clamp sparks, so keep it away from the battery."],
  ["OSHA 1910.147", "The lockout/tagout rule.", "Controls hazardous energy during service."],
  ["Energy sources", "Electrical, hydraulic, pneumatic, spring and gravity.", "Lock out all of them."],
  ["Lockout steps", "Prepare, notify, shut down, isolate, lock, release energy, verify.", "Follow your written procedure."],
  ["Verify before work", "Try to start the machine after locking out.", "Return the switch to off after testing."],
  ["Group lockout", "Several workers each add their own lock.", "Use a lockout hasp."],
  ["Lockout hasp", "A device that holds many locks.", "Machine stays locked until the last lock comes off."],
  ["Lock removal", "Only the person who put a lock on removes it.", "Special rules if they're gone."],
  ["Electrical shock factors", "Current, path, time and frequency.", "Current through the heart is most dangerous."],
  ["Wet conditions", "Water lowers skin resistance.", "Keep electrical work dry."],
  ["Damaged cords", "Cuts and exposed wires.", "Tag out and replace."],
  ["Three-prong plugs", "Plugs with a ground pin.", "Never cut off the ground pin."],
  ["Cheater plug", "An adapter that skips the ground.", "Don't use them."],
  ["Outlet testers", "Plug-in testers that check wiring.", "Find bad grounds and reversed wires."],
  ["GFCI testing", "Press test and reset monthly.", "Replace if it doesn't trip."],
  ["Electrical panel access", "Keep 3 feet clear in front of panels.", "Needed to shut off power fast."],
  ["Breaker labeling", "Labels showing what each breaker controls.", "Makes lockout faster."],
  ["Overhead power lines", "Lines above the shop lot.", "Keep tow trucks and ladders clear."],
  ["Portable lights", "Work lights with guards.", "Use rough-service or LED lights."],
  ["Charging stations (EV)", "High-power shop chargers.", "Keep cables off the floor where possible."],
  ["Battery charging area", "A dedicated area for charging.", "Ventilated and away from sparks."],
  ["Battery short circuit", "Metal across battery terminals.", "Huge current; burns and explosions."],
  ["Tool across terminals", "A wrench touching both posts.", "Remove the negative first."],
  ["Battery explosion", "Hydrogen ignited by a spark.", "Wear goggles around batteries."],
  ["Airbag disarm", "Disconnect battery and wait before airbag work.", "Follow the maker's wait time."],
  ["Live airbag handling", "Carry with the trim facing away from you.", "Place face up on the bench."],
  ["Deployed airbag", "Residue can irritate skin.", "Wear gloves and eye protection."],
  ["Seatbelt pretensioner", "A small charge that tightens belts in a crash.", "Treat like an airbag."],
  ["Static electricity", "Sparks from static buildup.", "Ground yourself before touching electronics."],
  ["Capacitors in shop equipment", "Equipment can hold charge after unplugging.", "Follow repair manuals."],
  ["Welding on cars", "Welding can damage modules.", "Disconnect the battery and modules as directed."],
  ["Jump pack safety", "Check polarity before connecting.", "Many have reverse protection, but not all."],
  ["Hybrid shutdown basics", "Ready off, key away, wait time.", "Follow the maker for HV work."],
  ["Orange cable rule", "Never cut or disconnect orange cables without training.", "They carry high voltage."],
  ["HV warning labels", "Yellow labels on HV parts.", "Respect them."],
  ["Electrical burn first aid", "Cool burns and get medical care.", "Internal damage may not be visible."],
  ["Shock victim rescue", "Don't touch them until power is off.", "Use a non-conductive tool if needed."],
  ["Call for shock injuries", "Always get medical help after a shock.", "Heart rhythm problems can show up later."],
  ["Electrical PPE program", "Rules for gloves, tools and training.", "NFPA 70E guides it."],
  ["Qualified electrician", "Building wiring and panel repairs are for licensed electricians.", "Techs shouldn't open shop electrical panels."],
  ["Electrical safety training (1910.332)", "OSHA training for workers who face electrical hazards.", "Covers safe practices for the work you actually do."]
],
X: [
  ["Eyewash station", "A station that flushes chemicals or debris out of your eyes with clean water.", "Flush for at least 15 minutes, then get checked."],
  ["Spill kit", "Absorbent pads, socks and granules kept ready to contain a fluid spill.", "Contain first, then clean. Keep spills out of floor drains."],
  ["Emergency action plan", "The shop's written plan for alarms, exits, head counts and reporting.", "OSHA 1910.38. Know your part in it."],
  ["Assembly point", "The meeting spot outside after an evacuation.", "Go there and stay until released."],
  ["Head count", "Checking everyone is out after an evacuation.", "Tell firefighters about anyone missing."],
  ["Exit route", "A clear path from any spot in the shop to the outside.", "At least 28 inches wide, never locked from inside."],
  ["Exit sign", "A lit sign marking the way out.", "Report burned-out signs."],
  ["911 call", "Give the address, what happened, how many are hurt, and stay on the line.", "Send someone to meet the ambulance."],
  ["First aid kit", "Supplies for treating small injuries until help arrives.", "Restock after every use."],
  ["ANSI Z308.1", "The standard for what workplace first aid kits contain.", "Look for it on the kit label."],
  ["First aid responder", "A worker trained to give first aid at the shop.", "Know who yours are."],
  ["Bloodborne pathogens", "Germs in blood, like hepatitis B and HIV, that can spread disease.", "Gloves on before you touch blood."],
  ["Universal precautions", "Treating all blood and body fluids as infectious.", "Gloves, then wash your hands after."],
  ["CPR", "Chest compressions (and breaths if trained) for someone whose heart has stopped.", "Hard and fast: 100–120 a minute, 2 inches deep."],
  ["AED", "Automated external defibrillator: gives a shock to restart a heart.", "Turn it on and follow the voice prompts."],
  ["Recovery position", "Laying a breathing, unresponsive person on their side.", "Keeps the airway open."],
  ["Direct pressure", "Pressing hard on a wound to stop bleeding.", "Don't lift to peek; add more cloth on top."],
  ["Tourniquet", "A tight band above a limb wound to stop life-threatening bleeding.", "Note the time you put it on."],
  ["Burn cooling", "Running cool water over a heat burn for at least 10 minutes.", "No ice, butter or creams."],
  ["Chemical burn", "Skin damage from acids, alkalis or other chemicals.", "Flush 15+ minutes and check the SDS."],
  ["Shock (medical)", "A dangerous drop in blood flow after injury.", "Lay them down, keep warm, call 911."],
  ["Heat exhaustion", "Heavy sweating, weakness, nausea and dizziness from heat.", "Cool place, water, rest."],
  ["Heat stroke", "Hot skin, confusion, maybe no sweating; the body can't cool itself.", "Call 911 and cool them fast."],
  ["Emergency shower", "A shower that drenches the whole body after a chemical splash.", "Stay under it 15 minutes."],
  ["10-second rule", "An eyewash or shower must be reachable within 10 seconds.", "From ANSI Z358.1."],
  ["Tepid water", "Lukewarm water, about 60–100 °F, used in eyewash stations.", "Comfortable enough to flush the full 15 minutes."],
  ["Weekly eyewash check", "Running a plumbed eyewash every week.", "Flushes out stale water and proves it works."],
  ["Poison Control", "The U.S. poison help line: 1-800-222-1222.", "Have the SDS ready when you call."],
  ["Embedded object", "Something stuck in the eye or skin.", "Don't pull it out. Stabilize it and get care."],
  ["Near miss", "An event that could have hurt someone but didn't.", "Report it so it gets fixed."],
  ["Incident report", "A written account of an injury or near miss.", "Fill it out the same day."],
  ["OSHA 300 log", "The record of work-related injuries and illnesses.", "Most employers with more than 10 workers keep one."],
  ["Severe injury report", "Telling OSHA about a death within 8 hours, or a hospitalization, amputation or eye loss within 24.", "From 29 CFR 1904.39."],
  ["Whistleblower protection", "The law that protects workers who report hazards or injuries.", "OSH Act Section 11(c)."],
  ["Shelter in place", "Staying inside a safe room during severe weather or an outside hazard.", "Know where the shelter area is."],
  ["Gas leak response", "Get out, don't touch switches, call from outside.", "Sparks from a light switch can ignite gas."],
  ["Spill response", "Stop the source, contain, absorb, report.", "Big or unknown spills: leave and get help."],
  ["Frostbite", "Frozen skin from cold or escaping refrigerant.", "Warm gently with lukewarm water; don't rub."],
  ["Emergency numbers posted", "911 and key numbers posted by phones.", "Include the shop address."],
  ["Know your address", "Give the exact address to 911.", "Post it near the phone."],
  ["Evacuation alarm", "Signal to leave the building.", "Know the sound."],
  ["Evacuation route map", "Posted map of exits.", "Check the nearest exit."],
  ["Exit doors", "Must open easily from inside.", "Never block or lock them during work hours."],
  ["Emergency lighting", "Lights that work during power loss.", "Test them regularly."],
  ["Tornado / severe weather", "Shelter areas inside the building.", "Know where to go."],
  ["Fire evacuation", "Leave right away; close doors behind you.", "Don't go back for tools."],
  ["Accountability", "Making sure everyone is out.", "Report missing people to firefighters."],
  ["Customer safety", "Keep customers out of the shop area.", "They don't know the hazards."],
  ["Eye injury", "Chemical or particle in the eye.", "Flush at the eyewash for 15 minutes; get help."],
  ["Particle in eye", "Debris stuck in the eye.", "Don't rub; flush and get medical care."],
  ["Hearing injury", "Sudden loud noise or blow.", "Get it checked."],
  ["Cuts", "Lacerations from sharp metal.", "Direct pressure; deep cuts need medical care."],
  ["Crush injury", "Hands or feet crushed.", "Call 911 for serious crush injuries."],
  ["Amputation", "Losing a finger or limb.", "Call 911; save the part wrapped and cool, not on ice directly."],
  ["Fracture", "A broken bone.", "Don't move it; call for help."],
  ["Head injury", "A hit to the head.", "Watch for confusion and vomiting; get care."],
  ["Back injury", "Strains from lifting.", "Lift with legs; get help for heavy parts."],
  ["Lifting technique", "Bend knees, keep the load close, don't twist.", "Use carts and hoists."],
  ["Falls", "Slips and falls from height.", "Use proper ladders, not lifts or tires."],
  ["Ladder safety", "Three points of contact; proper angle.", "Inspect before use."],
  ["Slips on oil", "Oil spills cause falls.", "Clean spills right away."],
  ["Thermal burns", "Burns from hot parts.", "Cool with running water."],
  ["Exhaust burns", "Touching hot exhaust parts.", "Let them cool before working."],
  ["Coolant burns", "Hot coolant spray.", "Never open a hot radiator cap."],
  ["Chemical in mouth", "Swallowed chemical.", "Call Poison Control; follow the SDS."],
  ["Inhalation first aid", "Breathing in fumes.", "Move to fresh air; call for help."],
  ["Fainting", "Sudden loss of consciousness.", "Lay them down; check breathing."],
  ["Seizure", "Uncontrolled shaking.", "Clear the area; don't hold them down."],
  ["Diabetic emergency", "Low blood sugar signs.", "Call for help; give sugar if they can swallow."],
  ["Allergic reaction", "Swelling and trouble breathing.", "Call 911; help with their auto-injector if they have one."],
  ["Heart attack signs", "Chest pain, shortness of breath, sweating.", "Call 911 right away."],
  ["Stroke signs (FAST)", "Face drooping, arm weakness, speech trouble, time to call.", "Call 911 fast."],
  ["Choking", "Can't breathe or talk.", "Use abdominal thrusts if trained."],
  ["First aid supplies check", "Restock the kit regularly.", "Assign someone to check it."],
  ["Gloves in first aid", "Wear gloves when treating injuries.", "Protects you from blood."],
  ["Reporting injuries", "Tell your supervisor about any injury.", "Even small ones; it helps workers' comp."],
  ["Workers' compensation", "Insurance for work injuries.", "Report injuries right away."],
  ["OSHA 8-hour report", "A work-related death must be reported to OSHA within 8 hours.", "29 CFR 1904.39."],
  ["OSHA 24-hour report", "In-patient hospitalization, amputation or eye loss within 24 hours.", "29 CFR 1904.39."],
  ["Record keeping retention", "OSHA logs kept for 5 years.", "29 CFR 1904.33."]
]
};
